// v0.59 data corrections and defaults
(function(){
  var root = (typeof window !== 'undefined') ? window : globalThis;
  var D = root.DAMEKE_DATA;
  var G = root.DAMEKE_GENERATED_DATA;

  var ITEM_RENAMES = {
    'ノーマルのジュエル': 'ノーマルジュエル',
    'かくとうのジュエル': 'かくとうジュエル',
    'エスパーのジュエル': 'エスパージュエル',
    'ゴーストのジュエル': 'ゴーストジュエル',
    'ドラゴンのジュエル': 'ドラゴンジュエル',
    'フェアリーのジュエル': 'フェアリージュエル',
    'ぼうごパッド': 'ぼうごパット'
  };
  var ITEM_ID_RENAMES = {
    'ノーマルのジュエル': 'ノーマルジュエル',
    'かくとうのジュエル': 'かくとうジュエル',
    'エスパーのジュエル': 'エスパージュエル',
    'ゴーストのジュエル': 'ゴーストジュエル',
    'ドラゴンのジュエル': 'ドラゴンジュエル',
    'フェアリーのジュエル': 'フェアリージュエル',
    'ぼうごパッド': 'ぼうごパット'
  };

  function arr(x){ return Array.isArray(x) ? x : []; }
  function nameOf(x){ return x && x.name ? String(x.name) : ''; }
  function uniq(a){ var s=Object.create(null), out=[]; arr(a).forEach(function(v){ if(!v) return; v=String(v); if(s[v]) return; s[v]=1; out.push(v); }); return out; }
  function normalizePokemonName(name){
    name = name == null ? '' : String(name);
    return name.replace(/^(ケンタロス\((?:コンバット|ブレイズ|ウォーター)種\))(?:ｼｭ|シュ)$/u, '$1');
  }
  function normalizeIdFromName(name){
    return String(name || '').replace(/\s+/g,'_').replace(/[()（）\/・･]+/g,'_').replace(/_+/g,'_').replace(/^_|_$/g,'') || 'unknown';
  }
  function normalizePokemonList(list){
    var seen = Object.create(null);
    var out = [];
    arr(list).forEach(function(p){
      if(!p) return;
      var n = normalizePokemonName(p.name);
      p.name = n;
      p.id = normalizePokemonName(p.id || normalizeIdFromName(n));
      p.speciesKey = normalizePokemonName(p.speciesKey || n);
      p.formKey = normalizePokemonName(p.formKey || n);
      p.baseSpecies = normalizePokemonName(p.baseSpecies || n).replace(/\(.*\)$/,'');
      p.abilities = uniq(p.abilities);
      if(n === 'ヌケニン' && p.baseStats) p.baseStats.H = 1;
      var key = p.name;
      if(seen[key]) return;
      seen[key] = 1;
      out.push(p);
    });
    return out;
  }
  function normalizeItems(list){
    var seen = Object.create(null);
    var out = [];
    arr(list).forEach(function(item){
      if(!item) return;
      if(ITEM_RENAMES[item.name]) item.name = ITEM_RENAMES[item.name];
      if(ITEM_ID_RENAMES[item.id]) item.id = ITEM_ID_RENAMES[item.id];
      item.effectTags = uniq(item.effectTags);
      var key = item.name || item.id;
      if(seen[key]) return;
      seen[key] = 1;
      out.push(item);
    });
    out.sort(function(a,b){
      if(a.name === 'なし') return -1;
      if(b.name === 'なし') return 1;
      return 0;
    });
    return out;
  }
  function normalizeAbilities(list){
    var seen = Object.create(null);
    var out = [];
    arr(list).forEach(function(a){
      if(!a) return;
      a.effectTags = uniq(a.effectTags);
      var key = a.name || a.id;
      if(seen[key]) return;
      seen[key] = 1;
      out.push(a);
    });
    out.sort(function(a,b){
      if(a.name === 'なし') return -1;
      if(b.name === 'なし') return 1;
      return 0;
    });
    return out;
  }
  function findPokemon(name){
    var list = arr(D && D.pokemons);
    for(var i=0;i<list.length;i++) if(list[i] && list[i].name === name) return list[i];
    return null;
  }
  function firstAbility(name){
    var p = findPokemon(name);
    return p && p.abilities && p.abilities[0] ? p.abilities[0] : 'なし';
  }
  function setValueIfExists(el, value){
    if(!el || value == null) return false;
    try{ el.value = value; el.dispatchEvent(new Event('input', {bubbles:true})); el.dispatchEvent(new Event('change', {bubbles:true})); return true; }catch(e){ return false; }
  }
  function byCandidates(cands){
    for(var i=0;i<cands.length;i++){
      var el = document.getElementById(cands[i]) || document.querySelector('[name="'+cands[i]+'"]');
      if(el) return el;
    }
    return null;
  }
  function setDefaults(){
    if(!D) return;
    var defaults = { attacker:'ジュペッタ', defender:'ハバタクカミ', move:'シャドークロー' };
    var attackerAbility = firstAbility(defaults.attacker);
    var defenderAbility = firstAbility(defaults.defender);

    var pairs = [
      [['attackerPokemon','attackerName','atkPokemon','pokemonAttacker','attacker-pokemon','attacker'], defaults.attacker],
      [['defenderPokemon','defenderName','defPokemon','pokemonDefender','defender-pokemon','defender'], defaults.defender],
      [['move','moveName','selectedMove','moveInput','attackMove','attack-move'], defaults.move],
      [['attackerItem','atkItem','itemAttacker','attacker-item'], 'なし'],
      [['defenderItem','defItem','itemDefender','defender-item'], 'なし'],
      [['attackerAbility','atkAbility','abilityAttacker','attacker-ability'], attackerAbility],
      [['defenderAbility','defAbility','abilityDefender','defender-ability'], defenderAbility]
    ];
    pairs.forEach(function(p){ setValueIfExists(byCandidates(p[0]), p[1]); });
  }

  if(G){
    G.pokemons = normalizePokemonList(G.pokemons);
    G.items = normalizeItems(G.items);
    G.abilities = normalizeAbilities(G.abilities);
  }
  if(D){
    if(Array.isArray(D.pokemons)) D.pokemons = normalizePokemonList(D.pokemons);
    if(Array.isArray(D.items)) D.items = normalizeItems(D.items);
    if(Array.isArray(D.abilities)) D.abilities = normalizeAbilities(D.abilities);
    if(typeof D.normalizeCanonicalData === 'function') D.normalizeCanonicalData();

    D.v059CorrectionReport = function(){
      function countCanEvolve(){ var c=0; arr(D.pokemons).forEach(function(p){ if(p && p.canEvolve) c++; }); return c; }
      function hasItem(n){ return arr(D.items).some(function(x){ return x && x.name === n; }); }
      function hasPokemon(n){ return arr(D.pokemons).some(function(x){ return x && x.name === n; }); }
      return {
        canEvolveCount: countCanEvolve(),
        taurosCombatUnified: hasPokemon('ケンタロス(コンバット種)') && !hasPokemon('ケンタロス(コンバット種)ｼｭ') && !hasPokemon('ケンタロス(コンバット種)シュ'),
        renamedItems: {
          normalGem: hasItem('ノーマルジュエル'),
          fightingGem: hasItem('かくとうジュエル'),
          psychicGem: hasItem('エスパージュエル'),
          ghostGem: hasItem('ゴーストジュエル'),
          dragonGem: hasItem('ドラゴンジュエル'),
          fairyGem: hasItem('フェアリージュエル'),
          protectivePads: hasItem('ぼうごパット')
        },
        firstItem: arr(D.items)[0] && arr(D.items)[0].name,
        firstAbility: arr(D.abilities)[0] && arr(D.abilities)[0].name,
        defaultPlan: { attacker:'ジュペッタ', defender:'ハバタクカミ', move:'シャドークロー', attackerAbility:firstAbility('ジュペッタ'), defenderAbility:firstAbility('ハバタクカミ'), item:'なし' }
      };
    };
  }

  if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded', setDefaults);
  else setTimeout(setDefaults, 0);
  window.addEventListener('load', function(){ setTimeout(setDefaults, 0); setTimeout(setDefaults, 200); });
})();
