  function byName(list,name){ return arr(list).find(function(x){ return x && x.name === name; }) || null; }
  function eachDataset(fn){ [G,D].forEach(function(X){ if(X) fn(X); }); }
  function addTags(obj,tags,field){ field = field || 'tags'; if(!obj) return; obj[field] = uniq(arr(obj[field]).concat(tags)); }
  function move(name){ return D && byName(D.moves,name); }
  function item(name){ return D && byName(D.items,name); }

